import FWCore.ParameterSet.Config as cms

############################################################
# cmsDriver customisations for the Bs -> tau(3pi) tau(3pi) Phase-2 HLT path.
#
# Usage (the base config is generated by the standard machinery, so the menu
# stays exactly the stock one plus our path):
#
#   cmsDriver.py BsTauTauHLT -s HLT:75e33 --processName=HLTX \
#       --conditions auto:phase2_realistic_T33 --geometry ExtendedRun4D110 \
#       --era Phase2C17I13M9 --eventcontent FEVTDEBUGHLT --datatier GEN-SIM-DIGI-RAW \
#       --filein <file> -n 100 --no_exec \
#       --customise HLTrigger/BsToTauTau/customiseBsTauTauHLT.customiseBsTauTauHLT
#
# For timing, use customiseBsTauTauHLTOnly instead: it strips every other HLT
# path, so FastTimerService measures this path and nothing else.
############################################################


def customiseAddL1TrackClusters(process, withGT=True):
    """Emulate the GTT front end, the CLUE clustering and the GT seed.

    Phase2Spring24 GEN-SIM-DIGI-RAW-MINIAOD already stores the L1 tracks, so the
    expensive track finding is not repeated -- only the cheap GTT front end. The
    clusters do not exist in any released sample, so this has to run in the same
    job as the HLT path.
    """
    from L1Trigger.L1TTrackMatch.l1tGTTInputProducer_cfi import l1tGTTInputProducer
    from L1Trigger.L1TTrackMatch.l1tTrackSelectionProducer_cfi import l1tTrackSelectionProducer

    process.l1tGTTInputProducer = l1tGTTInputProducer.clone(
        l1TracksInputTag=cms.InputTag("l1tTTTracksFromTrackletEmulation", "Level1TTTracks")
    )
    process.l1tTrackSelectionProducer = l1tTrackSelectionProducer.clone()

    process.load("L1Trigger.L1TrackCluster.l1tTrackClustersCLUE_cff")

    if not withGT:
        # Cluster production only. Used on Phase2Spring24, where the GT cannot
        # run at all (see HLTL1TrackClusterFilter.cc): l1t::TrackerMuon changed
        # schema between 140X and this release, so l1tTkMuonsGmt is unreadable,
        # and L1GTProducer consumes it whether or not the menu uses muons.
        process.l1tBsTauTauClusterPath = cms.Path(
            process.l1tGTTInputProducer
            + process.l1tTrackSelectionProducer
            + process.l1tTrackClustersCLUE
        )
        process.schedule.insert(0, process.l1tBsTauTauClusterPath)
        return process

    # Publish the clusters to the GT through a GTT jet slot. This displaces the
    # real GTT prompt jets, which is acceptable for a standalone prototype only;
    # WP2 of the plan adds a dedicated slot to L1GTProducer. Anything in the menu
    # that seeds on GTTPromptJets is invalid in a job customised this way.
    process.load("L1Trigger.Phase2L1GT.l1tGTProducer_cff")
    process.l1tGTProducer.GTTPromptJets = cms.InputTag("l1tTrackClustersCLUE", "L1TrackClustersWord")

    # L1GTProducer consumes all 17 subsystem collections unconditionally -- there
    # is no "GTT jets only" switch -- so every one of them has to resolve or the
    # job dies on the first event. Phase2Spring24 does store them all, but it was
    # produced with 140X, where the standalone-muon instance names were
    # prompt/displacedSAMuons; 16_1_X renamed them to prompt/displaced. Without
    # this the job fails with ProductNotFound on std::vector<l1t::SAMuon>.
    process.l1tGTProducer.GMTSaPromptMuons = cms.InputTag("l1tSAMuonsGmt", "promptSAMuons")
    process.l1tGTProducer.GMTSaDisplacedMuons = cms.InputTag("l1tSAMuonsGmt", "displacedSAMuons")

    from L1Trigger.L1TrackCluster.l1tGTMenu_BsTauTauSeeds_cff import (
        BsTauTau6PiClusterPt20,
        BsTauTau6PiClusterPt30,
    )

    process.load("L1Trigger.Phase2L1GT.l1tGTAlgoBlockProducer_cff")
    process.BsTauTau6PiClusterPt20 = BsTauTau6PiClusterPt20
    process.BsTauTau6PiClusterPt30 = BsTauTau6PiClusterPt30

    process.pBsTauTau6PiClusterPt20 = cms.Path(process.BsTauTau6PiClusterPt20)
    process.pBsTauTau6PiClusterPt30 = cms.Path(process.BsTauTau6PiClusterPt30)

    process.l1tBsTauTauClusterPath = cms.Path(
        process.l1tGTTInputProducer
        + process.l1tTrackSelectionProducer
        + process.l1tTrackClustersCLUE
        + process.l1tGTProducer
    )
    process.l1tBsTauTauAlgoBlockPath = cms.Path(process.l1tGTAlgoBlockProducer)

    # The L1 emulation must precede every HLT path that seeds on it.
    process.schedule.insert(0, process.l1tBsTauTauClusterPath)
    process.schedule.insert(1, process.pBsTauTau6PiClusterPt20)
    process.schedule.insert(2, process.pBsTauTau6PiClusterPt30)
    process.schedule.insert(3, process.l1tBsTauTauAlgoBlockPath)

    return process


def customiseAddBsTauTauPath(process, seedOnGT=True):
    """Add HLT_BsToTauTau3Pi3Pi to an existing HLT process."""
    # process.load rather than importing the Path object: loading attaches every
    # module in the cfi's namespace to the process, which is what gives them
    # labels. Assigning the bare Path fails with "an entry has no label".
    process.load("HLTrigger.BsToTauTau.HLT_BsToTauTau3Pi3Pi_cfi")

    if not seedOnGT:
        # Swap the GT-algorithm filter for the direct cluster filter. Same
        # selection, no GT dependency.
        process.HLT_BsToTauTau3Pi3Pi.replace(
            process.hltL1P2GTBsTauTauCluster, process.hltL1TrackClusterSeed
        )

    # Before HLTriggerFinalPath, which builds the trigger summary and must see
    # the path's filter results.
    index = len(process.schedule)
    for i, path in enumerate(process.schedule):
        if path.label_() in ("HLTriggerFinalPath", "HLTAnalyzerEndpath"):
            index = i
            break
    process.schedule.insert(index, process.HLT_BsToTauTau3Pi3Pi)

    if hasattr(process, "FEVTDEBUGHLToutput"):
        process.FEVTDEBUGHLToutput.outputCommands.extend(
            [
                "keep *_l1tTrackClustersCLUE_*_*",
                "keep *_hltBsTauTauTrackSelector_*_*",
                "keep *_hltBsTauTauCandidateProducer_*_*",
            ]
        )

    return process


def customiseDropOtherHLTPaths(process):
    """Keep only our path (plus the final/analyzer paths).

    Needed for any honest timing number: with the full menu in the schedule the
    FastTimerService total is dominated by paths this study does not use, and the
    shared tracking modules are charged to whichever path runs them first.
    """
    keep = ("HLT_BsToTauTau3Pi3Pi", "HLTriggerFinalPath", "HLTAnalyzerEndpath")
    l1Prefixes = ("l1tBsTauTau", "pBsTauTau6Pi")

    # EndPaths are kept unconditionally. An earlier version filtered them out
    # along with the physics paths, which dropped FEVTDEBUGHLToutput_step: the
    # job then ran to completion with rc=0 and wrote no output at all. Silent,
    # and only visible as a missing file at the end of a campaign.
    kept = [
        p
        for p in process.schedule
        if isinstance(p, cms.EndPath) or p.label_() in keep or p.label_().startswith(l1Prefixes)
    ]
    process.schedule = cms.Schedule(*kept)

    # TrigReport is where the path efficiency and rate come from; without this
    # the job prints nothing about how many events its filters accepted.
    process.options.wantSummary = cms.untracked.bool(True)
    return process


def customiseDropTriggerSummary(process):
    """Remove hltTriggerSummaryAOD.

    TriggerSummaryProducerAOD collects every L1/HLT trigger object in the event,
    not just the ones our filters saved, so on Phase2Spring24 it reads
    l1tTkMuonsGmt and dies on the same l1t::TrackerMuon schema break that stops
    the GT (see HLTL1TrackClusterFilter.cc). Nothing downstream of this study
    reads the summary -- the decision comes from TriggerResults and the
    candidates are in their own collections -- so dropping it costs nothing here.
    It would have to come back for a menu integration on a compatible sample.
    """
    for name in ("HLTriggerFinalPath",):
        path = getattr(process, name, None)
        if path is not None and hasattr(process, "hltTriggerSummaryAOD"):
            path.remove(process.hltTriggerSummaryAOD)
    return process


def customiseSlimOutput(process):
    """Keep only what this analysis reads.

    FEVTDEBUGHLT is several MB per event; a 60-file campaign at that size is tens
    of TB of NFS for products nothing downstream opens. This keeps the L1
    clusters, the HLT pion/tau/Bs candidates, the trigger decision and the beam
    spot -- everything needed for the efficiency, rate and mass plots.
    """
    if not hasattr(process, "FEVTDEBUGHLToutput"):
        return process

    process.FEVTDEBUGHLToutput.outputCommands = cms.untracked.vstring(
        "drop *",
        "keep *_l1tTrackClustersCLUE_*_*",
        "keep *_l1tTrackSelectionProducer_*_*",
        "keep *_hltBsTauTauTrackSelector_*_*",
        "keep *_hltBsTauTauCandidateProducer_*_*",
        "keep edmTriggerResults_*_*_*",
        "keep *_hltOnlineBeamSpot_*_*",
        "keep recoGenParticles_genParticles_*_*",
    )
    # Only accepted events are worth writing; the rate comes from TrigReport.
    process.FEVTDEBUGHLToutput.SelectEvents = cms.untracked.PSet(
        SelectEvents=cms.vstring("HLT_BsToTauTau3Pi3Pi")
    )
    return process


def customiseAddNtupliser(process, fileName="bsTauTauNtuple.root"):
    """Flatten the candidates into plain TTrees inside the job.

    From CMSSW_20_0_0 on the legacy reco:: formats have no writable dictionary
    (the io_v1:: migration), so the candidate collections cannot be written to a
    file at all and test/ntupliseCandidates.py -- which reads them with FWLite --
    cannot run. Doing the flattening in the same process avoids persistence
    entirely: the collections are used in memory and only doubles reach the disk.

    The analyzer sits in an EndPath so it sees *every* event, not just the
    accepted ones. That matters: the rate denominator and the cluster-level
    numbers are per-event quantities, and on a rejected event the candidate
    producers simply never ran, which the analyzer records as empty rather than
    as a missing event.
    """
    from HLTrigger.BsToTauTau.HLTBsTauTauNtupliser import HLTBsTauTauNtupliser

    # The generated cfi is a factory function in this release, not a module
    # object, so it is called rather than cloned.
    process.hltBsTauTauNtupliser = HLTBsTauTauNtupliser()
    process.TFileService = cms.Service(
        "TFileService", fileName=cms.string(fileName)
    )
    process.bsTauTauNtuplePath = cms.EndPath(process.hltBsTauTauNtupliser)
    process.schedule.append(process.bsTauTauNtuplePath)
    return process


def customiseBsTauTauHLTNoGTNtuple(process):
    """Campaign variant: the no-GT path plus the in-job ntupliser.

    This is what the CMSSW_20_0_0 campaign runs. The EDM output is reduced to
    TriggerResults, since nothing else can be persisted in this release.
    """
    process = customiseBsTauTauHLTNoGT(process)
    process = customiseDropOtherHLTPaths(process)
    process = customiseDropTriggerSummary(process)
    process = customiseAddNtupliser(process)

    if hasattr(process, "FEVTDEBUGHLToutput"):
        process.FEVTDEBUGHLToutput.outputCommands = cms.untracked.vstring(
            "drop *",
            "keep edmTriggerResults_*_*_*",
        )
    return process


def customiseRegionalTracking(process):
    """Swap the inclusive pixel tracking regions for cluster-seeded ones.

    Requires the hltPhase2LegacyTracking process modifier -- see
    hltBsTauTauRegionalTracking_cff.py for why, and for why this is a standalone
    prototype rather than something menu-safe.
    """
    from HLTrigger.BsToTauTau.hltBsTauTauRegionalTracking_cff import useClusterSeededRegions

    return useClusterSeededRegions(process)


def customiseBsTauTauHLT(process):
    """L1 clusters + the HLT path, on top of the stock menu (GT-seeded)."""
    process = customiseAddL1TrackClusters(process, withGT=True)
    process = customiseAddBsTauTauPath(process, seedOnGT=True)
    return process


def customiseBsTauTauHLTNoGT(process):
    """As customiseBsTauTauHLT, but seeding directly on the cluster collection.

    This is the variant that actually runs on Phase2Spring24 today. Prefer the
    GT-seeded one on any sample whose L1 objects this release can read.
    """
    process = customiseAddL1TrackClusters(process, withGT=False)
    process = customiseAddBsTauTauPath(process, seedOnGT=False)
    return process


def customiseBsTauTauHLTNoGTOnly(process):
    """No-GT variant with every other HLT path removed. Use this for campaigns."""
    process = customiseBsTauTauHLTNoGT(process)
    process = customiseDropOtherHLTPaths(process)
    process = customiseDropTriggerSummary(process)
    process = customiseSlimOutput(process)
    return process


def customiseBsTauTauHLTOnly(process):
    """As above, but with every other HLT path removed. Use this for timing."""
    process = customiseBsTauTauHLT(process)
    process = customiseDropOtherHLTPaths(process)
    return process
